#include <iostream>
#include <unordered_map>
#include <bitset>
#include <vector>
#include <cctype>
using namespace std;

using State = bitset<128>;

const int MOD = 1000000007;
const long long INV = 570000004LL;

int add(int a, int b) {
    a += b;
    if (a >= MOD) a -= MOD;
    return a;
}

int sub(int a, int b) {
    a -= b;
    if (a < 0) a += MOD;
    return a;
}

long long mul(long long a, long long b) {
    return (a * b) % MOD;
}

unordered_map<State, int> state_index;
int n, state_counter, transitions[65536][128];

int compute_state(State s) {
    auto it = state_index.find(s);
    if (it != state_index.end()) return it->second;
    int idx = state_counter++;
    state_index[s] = idx;
    for (int m = 0; m < (1 << n); ++m) {
        State next = s;
        for (int j = 0; j < (1 << n); ++j) {
            if (!next[j]) {
                for (int k = m & j; k; k -= k & -k) {
                    if (s[j ^ (k & -k)]) {
                        next[j] = 1;
                        break;
                    }
                }
            }
        }
        transitions[idx][m] = compute_state(next);
    }
    return idx;
}

int p_table[7][7], q_table[7][128];
long long dp_table[8][65536];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n;
    compute_state(State(1));

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            cin >> p_table[i][j];
            p_table[i][j] = (int)mul(p_table[i][j], INV);
        }
    }

    for (int i = 0; i < n; ++i) {
        for (int mask = 0; mask < (1 << n); ++mask) {
            q_table[i][mask] = 1;
            for (int k = 0; k < n; ++k) {
                int bit = (mask >> k) & 1;
                int val = bit ? p_table[k][i] : sub(1, p_table[k][i]);
                q_table[i][mask] = (int)mul(q_table[i][mask], val);
            }
        }
    }

    dp_table[0][0] = 1;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < state_counter; ++j) {
            for (int mask = 0; mask < (1 << n); ++mask) {
                dp_table[i+1][transitions[j][mask]] = add(dp_table[i+1][transitions[j][mask]], 
                                                          (int)mul(dp_table[i][j], q_table[i][mask]));
            }
        }
    }

    State target;
    target.flip();
    cout << dp_table[n][state_index[target]] << '\n';

    return 0;
}
